#include <iostream>
#include <vector>
#include <algorithm>
#include <cassert>
#include <chrono>
#include <ext/pb_ds/assoc_container.hpp>
using namespace std;
using namespace __gnu_pbds;

auto get_random = [] { char *p = new char; delete p; return (uint64_t) p; };

struct HashFunc {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }

    uint64_t operator()(uint64_t x) const {
        static const uint64_t seed = splitmix64(chrono::steady_clock::now().time_since_epoch().count() * (get_random() | 1));
        return splitmix64(x ^ seed);
    }
};

const int MODULUS_NUM = 1e9 + 7;

struct ModNumberType {
    int v;

    ModNumberType(long long val_in = 0) {
        if (val_in < 0) val_in %= MODULUS_NUM, val_in += MODULUS_NUM;
        if (val_in >= MODULUS_NUM) val_in %= MODULUS_NUM;
        v = (int)val_in;
    }

    static int extended_gcd(int a, int m, int &x, int &y) {
        if (m == 0) {
            x = 1; y = 0;
            return a;
        }
        int g = extended_gcd(m, a % m, y, x);
        y -= (a / m) * x;
        return g;
    }

    static int mod_inverse(int a, int m = MODULUS_NUM) {
        int x, y;
        extended_gcd(a, m, x, y);
        return (x % m + m) % m;
    }

    explicit operator int() const { return v; }

    ModNumberType& operator+=(const ModNumberType &other) {
        v += other.v;
        if (v >= MODULUS_NUM) v -= MODULUS_NUM;
        return *this;
    }

    ModNumberType& operator-=(const ModNumberType &other) {
        v -= other.v;
        if (v < 0) v += MODULUS_NUM;
        return *this;
    }

    ModNumberType& operator*=(const ModNumberType &other) {
        v = (uint64_t(v) * other.v) % MODULUS_NUM;
        return *this;
    }

    ModNumberType& operator/=(const ModNumberType &other) {
        return *this *= ModNumberType(mod_inverse(other.v));
    }

    friend ModNumberType operator+(const ModNumberType &a, const ModNumberType &b) { return ModNumberType(a) += b; }
    friend ModNumberType operator-(const ModNumberType &a, const ModNumberType &b) { return ModNumberType(a) -= b; }
    friend ModNumberType operator*(const ModNumberType &a, const ModNumberType &b) { return ModNumberType(a) *= b; }
    friend ModNumberType operator/(const ModNumberType &a, const ModNumberType &b) { return ModNumberType(a) /= b; }

    ModNumberType pow(long long p) const {
        assert(p >= 0);
        ModNumberType res = 1, base = *this;
        while (p > 0) {
            if (p & 1) res *= base;
            base *= base;
            p >>= 1;
        }
        return res;
    }
};

int main() {
    int N;
    cin >> N;
    vector<vector<ModNumberType>> prob(N, vector<ModNumberType>(N));
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            int p;
            cin >> p;
            prob[i][j] = ModNumberType(p) / ModNumberType(100);
        }

    vector<vector<int>> count_mask(N + 1);
    vector<int> index_map(1 << N, -1);
    for (int msk = 0; msk < (1 << N); ++msk) {
        int c = __builtin_popcount(msk);
        index_map[msk] = (int)count_mask[c].size();
        count_mask[c].push_back(msk);
    }

    gp_hash_table<long long, ModNumberType, HashFunc> state_map;
    state_map[1LL << index_map[0]] = ModNumberType(1);

    for (int left_idx = 0; left_idx < N; ++left_idx) {
        gp_hash_table<long long, ModNumberType, HashFunc> new_state_map;
        vector<ModNumberType> prod_mask(1 << N, ModNumberType(1));
        for (int mask = 0; mask < (1 << N); ++mask) {
            for (int col = 0; col < N; ++col) {
                if (mask & (1 << col))
                    prod_mask[mask] *= prob[left_idx][col];
                else
                    prod_mask[mask] *= (ModNumberType(1) - prob[left_idx][col]);
            }
        }

        vector<long long> new_bits(N, 0);
        vector<ModNumberType> new_possible(1 << N, ModNumberType(0));

        for (auto &entry : state_map) {
            long long mask_state = entry.first;
            ModNumberType prob_state = entry.second;
            fill(new_bits.begin(), new_bits.end(), 0);
            for (int m : count_mask[left_idx]) {
                if ((mask_state >> index_map[m]) & 1) {
                    for (int i = 0; i < N; ++i) {
                        if (((m >> i) & 1) == 0) {
                            new_bits[i] |= 1LL << index_map[m | (1 << i)];
                        }
                    }
                }
            }
            fill(new_possible.begin(), new_possible.end(), ModNumberType(0));
            for (int current_mask = 1; current_mask < (1 << N); ++current_mask) {
                int ctz = __builtin_ctz(current_mask);
                new_possible[current_mask] = new_possible[current_mask & (current_mask - 1)] | new_bits[ctz];
                long long combined_mask = new_possible[current_mask];
                new_state_map[combined_mask] += prob_state * prod_mask[current_mask];
            }
        }
        state_map = move(new_state_map);
    }

    ModNumberType total = 0;
    for (auto &entry : state_map) {
        if (((entry.first >> index_map[(1 << N) - 1]) & 1) != 0)
            total += entry.second;
    }
    cout << (int)total << '\n';
}
